import{_ as a,o as e,c as o,ag as d}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"无为","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-无为.md","filePath":"50-概念资料/dict-无为.md","lastUpdated":1778040484000}'),l={name:"50-概念资料/dict-无为.md"};function r(i,t,u,h,c,n){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="无为" tabindex="-1">无为 <a class="header-anchor" href="#无为" aria-label="Permalink to &quot;无为&quot;">​</a></h1><blockquote><p>传统：道家/通用 | 佛家对应：无住 | 儒家对应：无为而治</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>无为了空居士教导中最容易被误解的词汇之一。他反复澄清：无为不是什么都不做，是<strong>无妄为</strong>——不违背客观规律地去乱搞。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;无为不是什么都不做，是无妄为——不违背客观规律去乱搞。&quot;</p></blockquote><blockquote><p>&quot;无为就是按照客观实际情况去做。该怎么做就怎么做，不添加个人主观的妄念。&quot;</p></blockquote><blockquote><p>&quot;一切贤圣，皆以无为法而有差别——方法有快慢，但都是为了到彼岸。无为法就是最自然的方法。&quot;</p></blockquote><blockquote><p>&quot;观天之道，执天之行——观察大自然的规律，并以此规范我们的行为。&quot;</p></blockquote><h2 id="无为的日常应用" tabindex="-1">无为的日常应用 <a class="header-anchor" href="#无为的日常应用" aria-label="Permalink to &quot;无为的日常应用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>有为（错误的）</th><th>无为（正确的）</th></tr></thead><tbody><tr><td>教育孩子</td><td>强迫孩子按自己的方式学习</td><td>观察孩子的特点，因材施教</td></tr><tr><td>工作</td><td>为了加班而加班，做无用功</td><td>找到最高效的方法，做好该做的</td></tr><tr><td>静坐</td><td>拼命压念头、追求境界</td><td>心平气和，似守非守</td></tr><tr><td>人际关系</td><td>刻意讨好、控制</td><td>真诚相待，自然而然</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-自然">自然</a> — 无为就是按照自然规律行事</li><li><a href="/50-概念资料/dict-不二">不二</a> — 无为超越了&quot;做&quot;和&quot;不做&quot;的二元对立</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-自然务实">自然务实</a> — 无为的实证方法</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>遇到问题，先观察规律，再行动</li><li>不做多余的事——刚好到那个度就停了</li><li>&quot;因上精进，果上随缘&quot;——努力但不强求</li></ul>',17)])])}const b=a(l,[["render",r]]);export{s as __pageData,b as default};
